// Performance (Gen 1), converted from Rectangular Starlink.obj + its Base.obj —
// a 513 mm panel on a vertical arm, 405 mm from panel face to foot. Same body as
// the v3 Standard Actuated.
//
// It ships as two files that do NOT share a pose, and unlike the round dish it will
// not seat by sliding: the arm is raked 30.12 deg off the panel normal. What gets
// rotated matters — the PANEL keeps the source frame, because buildDish aims model
// +z down the boresight and turning the panel would swing its face off the beam and
// lift the beam's origin off the surface. The arm, its fitting and the base are
// rotated up to vertical instead, about the pivot, which keeps the pivot's
// coordinates identical in both frames so one value serves each.
//
// The seat is measured, not fitted by eye: the base's bore is a vertical socket of
// radius 17.2 mm and the arm a cylinder of radius 17.16 mm, and it is that
// agreement which fixes it. The arm's axis comes from PCA over its vertices.
//
// Articulated like the round dish: the panel tilts to the boresight while the arm
// and base stand upright, turning in azimuth only. The hardware is really a swivel
// — this model's collar is coaxial with the arm, not a transverse pin — but a
// swivel alone holds elevation fixed, so the head hinges and stays with its beam.
//
// longAxisMm is the assembly's widest span, not the panel's 513 mm: every sibling
// model's value equals its widest span, which is what makes them all draw the same
// size in the scene, and here the base is the wider part.
//
// Stored as int16 units of 1/50 mm — the assembly stands 405 mm tall, which
// overflows the sixty-fourths the round dish uses. Reduction is the Standard's:
// coincident weld, then quadric edge collapse, run on each solid alone so the panel
// keeps its budget.
import type { DishModelMesh } from "./types";
export const performanceGen1Dish: DishModelMesh = {
  scale: 50,
  longAxisMm: 562,
  // panel face, its dark edge ribbon — then the arm, its lower fitting and the
  // base, which do not tilt.
  parts: [
    [0, 2514, 0.95],
    [2514, 286, 0.4],
    [2800, 700, 0.4],
    [3500, 200, 0.4],
    [3700, 1000, 0.4],
  ],
  joint: { baseVertex: 1402, pivot: [-5, -612, -2708] },
  positions:
    "",
  indices:
    "",
};
